#include "stdafx.h"#include "HcdSheet.h"KHcdSheet::KHcdSheet(){}void KHcdSheet::ProjectRestored( IHcdController *pCtrl ){  SProjRestedParams params;  params.pCtrl = pCtrl;  for( DWORD i=0; i<m_nPages; ++i )  {    m_pPages[i].ProjectRestored( params, 0 );  }  for( DWORD i=0; i<m_nPages; ++i )  {    m_pPages[i].ProjectRestored( params, 1 );  }}void KHcdSheet::LinkPageConnections( IHcdController *pCtrl ){  SProjRestedParams params;  params.pCtrl = pCtrl;  for( DWORD i=0; i<m_nPages; ++i )  {    m_pPages[i].ProjectRestored( params, 2 );    m_pPages[i].LinkPageConnections();  }}void KHcdSheet::StepCalc( SStepCalcParams &params ){  for( DWORD n=0; n<m_nPages; ++n )  {    m_pPages[n].StepCalc( params );  }}LPCSTR KHcdSheet::GetTreeName(){  if( !m_szTreeName[0] )    sprintf_s( m_szTreeName, "%s - %s ", szTitle, szDescription );  return m_szTreeName;}size_t KHcdSheet::GetChild( IHcdDrawable **ppBuf, size_t count ){  if( !count )    return m_nPages;  size_t p = 0;  for( DWORD i=0; i<m_nPages && p<count; ++p, ++i )    ppBuf[p] = &m_pPages[i];  return p;}size_t KHcdSheet::GetLogixBlocks( IHcdElement **ppBuf, size_t count ){  return 0;}enum EKeys{  sKeyPageCount = 0x49200937,  sKeyPage      = 0x3F1CD978,  sKeyEndPages  = 0x8105F00C,};int KHcdSheet::SaveState( IStateSer &saver, DWORD ver ){  saver.Write( sKeyPageCount );  saver.Write( m_nPages );  for( DWORD n=0; n<m_nPages; ++n )  {    KHcdPage *pPage = &m_pPages[n];    saver.Write( sKeyPage );    saver.Write( pPage->GetTreeName() );    saver.Write( pPage->nPage );    DWORD posStart = saver.GetPosition();    DWORD l = saver.Write( posStart );    pPage->SaveState( saver, ver );    DWORD posEnd = saver.GetPosition();    DWORD length = posEnd - posStart - l;    saver.WriteAtPosition( posStart, length );  }  saver.Write( sKeyEndPages );  return 0;}int KHcdSheet::RestoreState( IStateSer &restorer, DWORD savedVer ){  EKeys key;  DWORD savedCount = 0;char buffer[128];  DWORD NP;  DWORD length = 0;  restorer.Read( key );  ASSD( sKeyPageCount==key );  if( sKeyPageCount!=key )    return 2;  restorer.Read( savedCount );  for( size_t s=0; s<savedCount; ++s )  {    restorer.Read( key );    ASSD( sKeyPage==key );    DWORD L = restorer.Read( buffer );    ASSD( L );    restorer.Read( NP );    restorer.Read( length );    KHcdPage *pP = NULL;    for( DWORD n=0; n<m_nPages; ++n )    {      KHcdPage *pPage = &m_pPages[n];      if( pPage->nPage!=NP )        continue;;      ASSD( !strcmp(pPage->GetTreeName(), buffer) );      pP = pPage;      break;    }    ASSD( pP );    pP->RestoreState( restorer, savedVer );  }  restorer.Read( key );  ASSD( sKeyEndPages==key );  if( sKeyEndPages!=key )    return 3;  return 0;}